const char* const kAutoFaces[] = {
    "Neutral", "Joy", "JoyBlush", "Blushing", "AngryHappy", "Angry", "Annoyed", "Spooked", "Questioning", "Exclamation", "Dead", "Squinting", "Dizzy", "HeartEyes", "UWU", "OWO", "Crying"
};
const int kAutoFaceCount = 17;

const char* const kBootFaces[] = {
    "Neutral", "Joy", "UWU", "OWO", "Spooked", "HeartEyes", "Questioning"
};
const int kBootFaceCount = 7;

const Emotion* find_emotion(std::string_view id) {
  for (int i = 0; i < kEmotionCount; ++i) {
    if (id == kEmotions[i].id) {
      return &kEmotions[i];
    }
  }
  return nullptr;
}

const Emotion* emotion_at(int index) {
  if (index < 0 || index >= kEmotionCount) {
    return nullptr;
  }
  return &kEmotions[index];
}

const char* kind_name(Kind kind) {
  return kind == Kind::Special ? "special" : "classic";
}

const char* effect_name(Effect effect) {
  switch (effect) {
    case Effect::Snarl:
      return "snarl";
    case Effect::Dizzy:
      return "dizzy";
    case Effect::Wink:
      return "wink";
    case Effect::Randomize:
      return "randomize";
    case Effect::Glitch:
      return "glitch";
    default:
      return "none";
  }
}

